package com.mendes.scheduling_platform.blockedperiod; import com.mendes.scheduling_platform.exception.*; import com.mendes.scheduling_platform.venue.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class BlockedPeriodService { private final BlockedPeriodRepository repo;private final VenueRepository venues;public BlockedPeriodService(BlockedPeriodRepository r,VenueRepository v){repo=r;venues=v;}public List<BlockedPeriod> list(Long t,Long v){return repo.findAllByTenantIdAndVenueId(t,v);}public BlockedPeriod save(Long t,Long v,BlockedPeriod b){venues.findByIdAndTenantId(v,t).orElseThrow(()->new NotFoundException("Espaço não encontrado"));if(!b.getStartDateTime().isBefore(b.getEndDateTime()))throw new BusinessException("Intervalo inválido");b.setId(null);b.setTenantId(t);b.setVenueId(v);return repo.save(b);}public void delete(Long t,Long id){repo.delete(repo.findByIdAndTenantId(id,t).orElseThrow(()->new NotFoundException("Bloqueio não encontrado")));}}
